/* Export the model as CSS custom properties, JSON, or SVG. */
(function () {
  const G = (globalThis.GridCalc = globalThis.GridCalc || {});
  if (typeof module !== 'undefined') { require('./math.js'); require('./scene.js'); }
  const { round } = G.math;

  const px = (v) => `${round(v, 2)}px`;

  function toCss(model) {
    const { cfg, unit: u, view, margins, grids, type, baseline } = model;
    const g = grids[0];
    const m = margins.snapped;
    const rows = [
      '/* Generated by Grid Calculator — every length is a multiple of --u when snapping is on. */',
      ':root {',
      `  --u: ${px(u)};`,
      `  --page-width: ${px(cfg.layout === 'spread' ? view.width / 2 : view.width)};`,
      `  --page-height: ${px(view.height)};`,
      `  --canon-division: ${cfg.divisions};`,
      `  --margin-top: ${px(m.top)};`,
      `  --margin-bottom: ${px(m.bottom)};`,
      `  --margin-inner: ${px(m.inner)};`,
      `  --margin-outer: ${px(m.outer)};`,
    ];
    if (g && g.ok) {
      rows.push(
        `  --columns: ${cfg.columns};`,
        `  --column-width: ${px(g.columns[0].w)};`,
        `  --gutter: ${px(cfg.gutter * u)};`,
        `  --rows: ${cfg.rows};`,
        `  --row-height: ${px(g.modules[0].h)};`,
        `  --row-gutter: ${px(cfg.rowGutter * u)};`,
        `  --block-width: ${px(g.fitted.w)};`,
        `  --block-height: ${px(g.fitted.h)};`,
      );
    }
    rows.push(`  --baseline: ${px(baseline.step)};`);
    type.scale.forEach((s) => rows.push(`  --font-size-${s.name}: ${px(s.size)};`, `  --line-height-${s.name}: ${px(s.leading)};`));
    rows.push('}', '');
    if (g && g.ok) {
      rows.push(
        '.grid {', '  display: grid;',
        '  grid-template-columns: repeat(var(--columns), var(--column-width));',
        '  column-gap: var(--gutter);', '  row-gap: var(--row-gutter);', '}', '',
      );
    }
    return rows.join('\n');
  }

  function toJson(model) {
    const { cfg, unit, view, margins, blocks, grids, type, baseline, integrity, stats } = model;
    return {
      foundations: { setUp: { gridUnit: unit, canvasWidth: view.width, canvasHeight: view.height, layout: cfg.layout } },
      grids: {
        villardDeHonnecourtCanon: {
          divisions: cfg.divisions, snapMode: cfg.snapMode, margins,
          workAreas: blocks.map((b) => ({ id: b.id, x: b.x, y: b.y, width: b.w, height: b.h, units: b.units, deviation: b.deviation })),
        },
        modular: grids.map((g) => ({
          block: g.block.id, columns: g.columns.map(({ x, y, w, h }) => ({ x, y, width: w, height: h })),
          gutter: cfg.gutter * unit, rows: cfg.rows, rowGutter: cfg.rowGutter * unit,
        })),
        baseline: { step: baseline.step, units: baseline.units, origin: baseline.origin },
      },
      typography: Object.fromEntries(type.scale.map((s) => [s.name, { fontFamily: cfg.fontFamily, fontSize: s.size, lineHeight: s.leading, lineHeightUnits: s.leadingUnits }])),
      integrity: { edges: integrity.total, onGrid: integrity.onGrid },
      stats,
      settings: cfg,
    };
  }

  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const n = (v) => round(v, 3);

  function toSvg(model, scene) {
    const { cfg, view } = model;
    const styles = G.scene.roleStyles(cfg);
    const body = scene.map((p) => {
      const st = styles[p.role] || {};
      if (p.t === 'line') {
        const dash = st.dash ? ` stroke-dasharray="${st.dash.join(' ')}"` : '';
        return `<line x1="${n(p.x1)}" y1="${n(p.y1)}" x2="${n(p.x2)}" y2="${n(p.y2)}" stroke="${st.stroke}" stroke-opacity="${st.alpha}" stroke-width="${n(st.w)}"${dash}/>`;
      }
      if (p.t === 'rect') {
        const fill = st.fill && p.fill !== false ? `fill="${st.fill}" fill-opacity="${st.fillAlpha}"` : 'fill="none"';
        const stroke = st.stroke ? `stroke="${st.stroke}" stroke-opacity="${st.alpha}" stroke-width="${n(st.w)}"` : 'stroke="none"';
        const dash = st.dash ? ` stroke-dasharray="${st.dash.join(' ')}"` : '';
        return `<rect x="${n(p.x)}" y="${n(p.y)}" width="${n(p.w)}" height="${n(p.h)}" ${fill} ${stroke}${dash}/>`;
      }
      if (p.role === 'label') return ''; // labels are screen-sized annotations; omitted from vector export
      const family = esc(p.family || 'sans-serif');
      return `<text x="${n(p.x)}" y="${n(p.y)}" font-family="${family}" font-size="${p.size}" font-weight="${p.weight || 'normal'}" fill="${st.fill}">${esc(p.str)}</text>`;
    }).filter(Boolean).join('\n  ');
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${view.width}" height="${view.height}" viewBox="0 0 ${view.width} ${view.height}">\n  <rect width="100%" height="100%" fill="${cfg.cBg}"/>\n  ${body}\n</svg>\n`;
  }

  G.exporters = { toCss, toJson, toSvg };
  if (typeof module !== 'undefined') module.exports = G.exporters;
})();
